// Une las dos ramas: con comentario (lo aplicó el modelo) o sin comentario (solo cambiaron precios).
// Nunca lanza: si algo no cuadra devuelve ok=false con el motivo, para marcar la propuesta en error.
const estado = $('Leer estado').first().json.body;
let p = estado.payload;
let reason = '';
if ($('Aplicar comentarios').isExecuted) {
  const ia = $('Aplicar comentarios').first().json;
  let c = ia && ia.message ? ia.message.content : null;
  if (!c) {
    reason = 'El modelo no respondió al aplicar los comentarios' + (ia && ia.error ? ': ' + (ia.error.message || ia.error) : '');
  } else {
    try {
      if (typeof c === 'string') c = c.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
      const parsed = typeof c === 'string' ? JSON.parse(c) : c;
      // El modelo a veces imita la forma de la entrada y devuelve {propuesta: {...}} (medido: ejecución 403689).
      const candidato = parsed && parsed.propuesta && typeof parsed.propuesta === 'object' ? parsed.propuesta : parsed;
      // Lo que el modelo omita se conserva de lo guardado: nunca se manda a WordPress un payload incompleto.
      p = Object.assign({}, estado.payload, candidato);
    } catch (e) {
      reason = 'El modelo devolvió un JSON inválido al aplicar los comentarios';
    }
  }
}
if (!reason && (!p || typeof p !== 'object')) reason = 'La propuesta no tiene un payload legible';
if (!reason) p.extra_slides = (p.extra_slides || []).slice(0, 2);
// WordPress restaura precios y unique_id de todos modos; aquí solo se asegura el formato.
return [{ json: { ok: !reason, reason, id: estado.id, unique_id: estado.unique_id, company: estado.company_name, payload: p } }];

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const br = (s) => esc(s).replace(/\n/g, '<br>');
const est = $('Leer estado').first().json.body;
const pf = $('Payload final').first().json;
const v = $('Vista previa').first().json;
const ok = !!v.view_url;
const html = `<div style="margin:0;padding:24px 12px;background:#eef2f6;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:0 auto;background:#ffffff;border-radius:14px;overflow:hidden;box-shadow:0 2px 10px rgba(13,27,42,.08);">
<tr><td style="background:#0d1b2a;padding:18px 24px;">
<table role="presentation" cellpadding="0" cellspacing="0"><tr>
<td style="vertical-align:middle;"><img src="https://automatizatech.cl/wp-content/themes/automatiza-tech/assets/images/logo-automatiza-tech.png" width="44" height="37" alt="AutomatizaTech" style="display:block;border:0;"></td>
<td style="vertical-align:middle;padding-left:12px;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#ffffff;font-size:16px;font-weight:700;">AutomatizaTech<br><span style="color:#00d9c0;font-size:12px;font-weight:600;letter-spacing:.04em;">Propuestas · aviso interno</span></td>
</tr></table>
</td></tr>
<tr><td style="height:4px;background:#00d9c0;line-height:4px;font-size:0;">&nbsp;</td></tr>
<tr><td style="padding:26px 24px 8px;">
<span style="display:inline-block;background:#dbeafe;color:#1e40af;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:12px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;padding:5px 12px;border-radius:999px;">Cambios aplicados</span>
<h1 style="margin:14px 0 16px;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:22px;line-height:1.3;color:#0d1b2a;">Cambios aplicados: ${esc(pf.company)}</h1>
${ok ? '' : `<div style="background:#fffbeb;border-left:4px solid #f59e0b;border-radius:8px;padding:14px 16px;margin:0 0 16px;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:14px;line-height:1.55;color:#334155;"><strong>La nueva vista previa no se pudo generar.</strong> Los cambios quedaron guardados; «Pedir cambios» sin comentario la vuelve a generar.</div>`}<p style="margin:0 0 14px;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:15px;line-height:1.55;color:#334155;"><strong>Tu comentario</strong></p><div style="background:#f8fafc;border-left:4px solid #cbd5e1;border-radius:8px;padding:14px 16px;margin:0 0 16px;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:14px;line-height:1.55;color:#334155;">${br(est.ultimo_comentario) || "(sin comentario: solo cambiaste precios)"}</div><p style="margin:0 0 14px;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:15px;line-height:1.55;color:#334155;">Tus precios se mantienen tal como los dejaste en el panel. No se ha gastado nada en fotos.</p><div style="margin:6px 0 4px;"><a href="https://automatizatech.cl/ver-presentacion.php?id=${esc(pf.unique_id)}" style="display:inline-block;background:#00d9c0;color:#0d1b2a;border:2px solid #00d9c0;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:15px;font-weight:700;text-decoration:none;padding:12px 22px;border-radius:10px;margin:6px 8px 6px 0;">👀 Ver la nueva vista previa</a><a href="https://automatizatech.cl/wp-admin/admin.php?page=automatiza-proposals&edit_id=${esc(pf.id)}" style="display:inline-block;background:#ffffff;color:#0d1b2a;border:2px solid #0d1b2a;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:15px;font-weight:700;text-decoration:none;padding:12px 22px;border-radius:10px;margin:6px 8px 6px 0;">✏️ Seguir revisando o aprobar</a></div>
</td></tr>
<tr><td style="padding:14px 24px 22px;border-top:1px solid #e2e8f0;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:12px;line-height:1.5;color:#64748b;">
Aviso automático del flujo de propuestas de AutomatizaTech. Nada de esto se envía al cliente: el envío lo haces tú desde el panel.
</td></tr>
</table>
</div>`;
return [{ json: { asunto: (ok ? '' : '⚠️ ') + pf.company + ' · cambios aplicados', html } }];

// Motivo legible para status_note, venga de donde venga el fallo (lectura, modelo o guardado).
const hook = $('Webhook').first().json.body || {};
let base = { id: hook.id, unique_id: '', company: `propuesta ${hook.id}`, reason: '' };
if ($('Payload final').isExecuted) {
  base = $('Payload final').first().json;
} else {
  const le = $('Leer estado').first().json;
  base.reason = `No se pudo leer la propuesta en WordPress (${le.statusCode ? 'HTTP ' + le.statusCode : 'sin respuesta' + (le.error && le.error.message ? ': ' + le.error.message : '')})`;
}
let reason = base.reason;
if (!reason && $('Guardar y volver a borrador').isExecuted) {
  const g = $('Guardar y volver a borrador').first().json;
  const msg = g.body && (g.body.message || g.body.code) ? ' — ' + (g.body.message || g.body.code) : '';
  reason = g.statusCode ? `WordPress rechazó el cambio (HTTP ${g.statusCode})${msg}`
    : `WordPress no respondió al guardar el cambio${g.error && g.error.message ? ': ' + g.error.message : ''}`;
}
return [{ json: { id: base.id, unique_id: base.unique_id, company: base.company, reason: reason || 'Error desconocido al aplicar los cambios', exec: $execution.id } }];
